function add(ch){stop();if(ch.id==='milo'){addObject('character');return;}remember();project.characters??={};if(!project.characters[ch.id])project.characters[ch.id]=clone(ch);const saved=project.characters[ch.id],o=M.make('character',frame().camera.x,frame().camera.y);Object.assign(o,{characterId:ch.id,name:saved.name,useViews:false,rig:{}});if(!saved.avatar){const v=saved.views.front||Object.values(saved.views)[0];o.h=350;o.w=350*v.width/v.height;o.view=saved.views.front?'front':Object.keys(saved.views)[0];}frame().objects.push(o);selected=[o.id];setTool('select');changed();toast(ch.name+' added. Choose a movement in Properties.')}
