function bindFace(){$$('#faceEnabled').forEach(i=>i.onchange=()=>{const h=faceHead();if(h){h.face??={};h.face.enabled=i.checked;drawPreview()}});$$('[data-face-prop]').forEach(i=>i.oninput=()=>{const h=faceHead();if(!h)return;h.face??={};h.face[i.dataset.faceProp]=i.type==='color'?i.value:Number(i.value);drawPreview()});$('#faceAutoColor').onclick=()=>{const h=faceHead();if(h?.face)delete h.face.patch;drawPreview()};syncFace()}
